class Solution {
public:
    vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies) {
        int n = favoriteCompanies.size();
        for (int i = 0; i < n; ++i) {
            sort(favoriteCompanies[i].begin(), favoriteCompanies[i].end());
        }

        vector<int> result;
        for (int i = 0; i < n; ++i) {
            bool isSubset = false;
            for (int j = 0; j < n; ++j) {
                if (favoriteCompanies[i].size() >= favoriteCompanies[j].size()) continue;

                if (includes(favoriteCompanies[j].begin(), favoriteCompanies[j].end(),
                             favoriteCompanies[i].begin(), favoriteCompanies[i].end())) {
                    isSubset = true;
                    break;
                }
            }
            if (!isSubset) {
                result.push_back(i);
            }
        }

        return result;
    }
};
